WITH filtered AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, CASE WHEN amount >= 3800 THEN 'High' WHEN amount >= 1000 THEN 'Medium' ELSE 'Low' END AS amount_level, COALESCE(merchant, 'UNKNOWN') AS resolved_merchant FROM transactions WHERE txn_time >= TIMESTAMP '2023-08-05 02:00:00' AND merchant IS NOT DISTINCT FROM 'Amazon'), gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM filtered), islands AS (SELECT id, account_id, txn_type, txn_time, is_flagged, resolved_merchant, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, MIN(txn_time) AS first_txn_time FROM islands GROUP BY DATE_TRUNC('MONTH', txn_time)
